<?php
$id=filter_var($_GET['id']??null,FILTER_VALIDATE_INT);$row=null;
if($id){$s=$conn->prepare('SELECT r.*,e.nome AS equipamento_nome,u.nome AS usuario_nome FROM reservas r INNER JOIN equipamentos e ON e.id=r.equipamento_id INNER JOIN usuarios u ON u.id=r.usuario_id WHERE r.id=?');$s->bind_param('i',$id);$s->execute();$row=$s->get_result()->fetch_assoc();if(!$row||(!admin()&&(int)$row['usuario_id']!==(int)$_SESSION['id'])){echo '<p>Reserva não encontrada.</p>';return;}}
if($_SERVER['REQUEST_METHOD']==='POST'){
try{
verify_csrf();$acao=$_POST['acao']??'';$uid=(int)$_SESSION['id'];$conn->begin_transaction();
if($acao==='criar'){
$equip=filter_var($_POST['equipamento_id']??null,FILTER_VALIDATE_INT);$data=$_POST['data_retirada']??'';$desc=trim($_POST['descricao_colaborador']??'');$d=DateTimeImmutable::createFromFormat('!Y-m-d',$data);if(!$equip||!$d||$d->format('Y-m-d')!==$data)throw new RuntimeException('Equipamento ou data inválidos.');
$s=$conn->prepare("SELECT nome,patrimonio FROM equipamentos WHERE id=? AND status='disponivel' FOR UPDATE");$s->bind_param('i',$equip);$s->execute();$e=$s->get_result()->fetch_assoc();if(!$e)throw new RuntimeException('Equipamento indisponível.');
$s=$conn->prepare("INSERT INTO reservas(usuario_id,equipamento_id,tipo_equipamento,descricao_colaborador,data_retirada,patrimonio_item,status) VALUES(?,?,?,?,?,?,'pendente')");$s->bind_param('iisssi',$uid,$equip,$e['nome'],$desc,$data,$e['patrimonio']);$s->execute();$rid=$conn->insert_id;
$s=$conn->prepare("UPDATE equipamentos SET status='reservado' WHERE id=?");$s->bind_param('i',$equip);$s->execute();log_event($conn,$rid,'criada','Reserva criada');
}else{
if(!$row)throw new RuntimeException('Reserva inexistente.');$rid=(int)$row['id'];$status=$row['status'];
if($acao==='editar'){
if(in_array($status,['cancelada','devolvida'],true))throw new RuntimeException('Reserva encerrada.');$data=$_POST['data_retirada']??'';$desc=trim($_POST['descricao_colaborador']??'');$d=DateTimeImmutable::createFromFormat('!Y-m-d',$data);if(!$d||$d->format('Y-m-d')!==$data)throw new RuntimeException('Data inválida.');$s=$conn->prepare('UPDATE reservas SET data_retirada=?,descricao_colaborador=? WHERE id=?');$s->bind_param('ssi',$data,$desc,$rid);$s->execute();log_event($conn,$rid,'editada','Dados da reserva editados');
}elseif($acao==='cancelar'||$acao==='devolver'){
if($acao==='cancelar'&&!in_array($status,['pendente','aprovada'],true))throw new RuntimeException('Esta reserva não pode ser cancelada.');if($acao==='devolver'&&$status!=='retirada')throw new RuntimeException('Somente equipamentos retirados podem ser devolvidos.');$novo=$acao==='cancelar'?'cancelada':'devolvida';$s=$conn->prepare('UPDATE reservas SET status=? WHERE id=?');$s->bind_param('si',$novo,$rid);$s->execute();$eid=(int)$row['equipamento_id'];$s=$conn->prepare("UPDATE equipamentos SET status='disponivel' WHERE id=?");$s->bind_param('i',$eid);$s->execute();log_event($conn,$rid,$acao==='cancelar'?'cancelada':'devolvida','Status alterado para '.$novo);
}elseif($acao==='aprovar'||$acao==='retirar'){
if(!admin())throw new RuntimeException('Acesso restrito.');$expected=$acao==='aprovar'?'pendente':'aprovada';if($status!==$expected)throw new RuntimeException('Transição de status inválida.');$novo=$acao==='aprovar'?'aprovada':'retirada';$s=$conn->prepare('UPDATE reservas SET status=? WHERE id=?');$s->bind_param('si',$novo,$rid);$s->execute();log_event($conn,$rid,$acao==='aprovar'?'aprovada':'retirada','Status alterado para '.$novo);
}else throw new RuntimeException('Ação inválida.');}
$conn->commit();flash('Operação concluída.');go('reservas');
}catch(Throwable $e){$conn->rollback();flash('Erro: '.$e->getMessage());go($id?'reserva&id='.$id:'reserva');}}
$eq=$conn->query("SELECT id,nome,patrimonio FROM equipamentos WHERE status='disponivel' ORDER BY nome");
?><h1><?=$row?'Reserva #'.(int)$row['id']:'Nova reserva'?></h1><?php if($row):?><p><b>Usuário:</b> <?=h($row['usuario_nome'])?> | <b>Equipamento:</b> <?=h($row['equipamento_nome'])?> | <b>Status:</b> <?=h($row['status'])?> | <b>Criada em:</b> <?=h($row['criado_em'])?></p><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="acao" value="<?=$row?'editar':'criar'?>"><?php if(!$row):?><label>Equipamento<select name="equipamento_id" required><option value="">Selecione</option><?php while($e=$eq->fetch_assoc()):?><option value="<?=$e['id']?>"><?=h($e['nome'].' - '.$e['patrimonio'])?></option><?php endwhile;?></select></label><?php endif;?><label>Data de retirada<input type="date" name="data_retirada" value="<?=h($row['data_retirada']??'')?>" required></label><label>Descrição / finalidade<textarea name="descricao_colaborador"><?=h($row['descricao_colaborador']??'')?></textarea></label><?php if(!$row||!in_array($row['status'],['cancelada','devolvida'],true)):?><button><?=$row?'Salvar alterações':'Criar reserva'?></button><?php endif;?></form>
<?php if($row):?><div class="actions"><?php $acoes=[];if(admin()&&$row['status']==='pendente')$acoes['aprovar']='Aprovar';if(admin()&&$row['status']==='aprovada')$acoes['retirar']='Registrar retirada';if($row['status']==='retirada')$acoes['devolver']='Registrar devolução';if(in_array($row['status'],['pendente','aprovada'],true))$acoes['cancelar']='Cancelar';foreach($acoes as $action=>$label):?><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="acao" value="<?=h($action)?>"><button><?=h($label)?></button></form><?php endforeach;?></div><?php endif;?>
